-- term_deposit: Fixed-term deposit (placement, maturity, rollover, premature withdrawal)
CREATE TABLE term_deposit (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  deposit_number               varchar(34) NOT NULL,
  customer_id                  uuid NOT NULL,
  product_id                   uuid NOT NULL,
  product_version_id           uuid NOT NULL,
  funding_account_id           uuid REFERENCES deposit_account(id),
  payout_account_id            uuid REFERENCES deposit_account(id),
  ledger_account_id            uuid,
  principal_amount             numeric(28,8) NOT NULL,
  currency                     char(3) NOT NULL,
  interest_rate                numeric(18,10) NOT NULL,
  day_count                    varchar(16) NOT NULL DEFAULT 'ACT_365',
  term_days                    integer NOT NULL,
  start_date                   date NOT NULL,
  maturity_date                date NOT NULL,
  interest_payout_mode         varchar(40) NOT NULL DEFAULT 'AT_MATURITY' CHECK (interest_payout_mode IN ('AT_MATURITY', 'MONTHLY_TO_ACCOUNT', 'QUARTERLY_TO_ACCOUNT', 'ANNUALLY_TO_ACCOUNT', 'UPFRONT')),
  rollover_instruction         varchar(40) NOT NULL DEFAULT 'PAY_OUT_ALL' CHECK (rollover_instruction IN ('ROLL_PRINCIPAL_AND_INTEREST', 'ROLL_PRINCIPAL_PAY_INTEREST', 'PAY_OUT_ALL')),
  auto_rollover_count          integer NOT NULL DEFAULT 0,
  expected_interest            numeric(28,8),
  accrued_interest             numeric(28,8) NOT NULL DEFAULT 0,
  premature_penalty_rate       numeric(18,10),
  allow_partial_withdrawal     boolean NOT NULL DEFAULT false,
  has_lien                     boolean NOT NULL DEFAULT false,
  status                       varchar(40) NOT NULL DEFAULT 'PENDING_FUNDING' CHECK (status IN ('PENDING_FUNDING', 'ACTIVE', 'MATURED', 'ROLLED_OVER', 'BROKEN', 'CLOSED', 'CANCELLED')),
  certificate_document_id      uuid,
  previous_deposit_id          uuid REFERENCES term_deposit(id),
  product_terms                jsonb,
  metadata                     jsonb,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_term_deposit_deposit_number UNIQUE (tenant_id, deposit_number),
  CONSTRAINT uq_term_deposit_ledger_account_id UNIQUE (tenant_id, ledger_account_id)
);
COMMENT ON TABLE term_deposit IS 'Fixed-term deposit (placement, maturity, rollover, premature withdrawal)';
COMMENT ON COLUMN term_deposit.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN term_deposit.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN term_deposit.created_at IS 'Creation time';
COMMENT ON COLUMN term_deposit.created_by IS 'Principal that created the row';
COMMENT ON COLUMN term_deposit.updated_at IS 'Last update time';
COMMENT ON COLUMN term_deposit.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN term_deposit.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN term_deposit.deposit_number IS 'Deposit reference number (server-generated)';
COMMENT ON COLUMN term_deposit.customer_id IS 'Customer';
COMMENT ON COLUMN term_deposit.product_id IS 'Product';
COMMENT ON COLUMN term_deposit.product_version_id IS 'Version pinned';
COMMENT ON COLUMN term_deposit.funding_account_id IS 'Account funded from';
COMMENT ON COLUMN term_deposit.payout_account_id IS 'Account receiving interest and principal';
COMMENT ON COLUMN term_deposit.ledger_account_id IS 'Ledger account';
COMMENT ON COLUMN term_deposit.principal_amount IS 'Placed amount';
COMMENT ON COLUMN term_deposit.currency IS 'Currency';
COMMENT ON COLUMN term_deposit.interest_rate IS 'Contracted annual rate';
COMMENT ON COLUMN term_deposit.day_count IS 'Day-count convention';
COMMENT ON COLUMN term_deposit.term_days IS 'Term in days';
COMMENT ON COLUMN term_deposit.start_date IS 'Value date of placement';
COMMENT ON COLUMN term_deposit.maturity_date IS 'Maturity date (holiday-adjusted)';
COMMENT ON COLUMN term_deposit.interest_payout_mode IS 'Interest payout';
COMMENT ON COLUMN term_deposit.rollover_instruction IS 'What happens at maturity';
COMMENT ON COLUMN term_deposit.auto_rollover_count IS 'Times rolled over';
COMMENT ON COLUMN term_deposit.expected_interest IS 'Interest at maturity if held to term';
COMMENT ON COLUMN term_deposit.accrued_interest IS 'Interest accrued so far';
COMMENT ON COLUMN term_deposit.premature_penalty_rate IS 'Rate reduction or penalty for breaking';
COMMENT ON COLUMN term_deposit.allow_partial_withdrawal IS 'Partial withdrawal allowed';
COMMENT ON COLUMN term_deposit.has_lien IS 'Pledged as collateral';
COMMENT ON COLUMN term_deposit.status IS 'Status';
COMMENT ON COLUMN term_deposit.certificate_document_id IS 'Deposit certificate';
COMMENT ON COLUMN term_deposit.previous_deposit_id IS 'Deposit it rolled over from';
COMMENT ON COLUMN term_deposit.product_terms IS 'Product terms pinned from the catalog at placement (copied on rollover)';
