-- standing_order: Recurring or future-dated payment instruction from an account
CREATE TABLE standing_order (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  deposit_account_id           uuid NOT NULL REFERENCES deposit_account(id),
  payee_id                     uuid,
  beneficiary_account_id       uuid REFERENCES deposit_account(id),
  amount                       numeric(28,8) NOT NULL,
  currency                     char(3) NOT NULL,
  reference                    varchar(140),
  frequency                    varchar(40) NOT NULL CHECK (frequency IN ('ONCE', 'DAILY', 'WEEKLY', 'BIWEEKLY', 'MONTHLY', 'QUARTERLY', 'SEMI_ANNUAL', 'ANNUAL')),
  day_of_period                integer,
  start_date                   date NOT NULL,
  end_date                     date,
  max_executions               integer,
  executions_done              integer NOT NULL DEFAULT 0,
  next_execution_date          date,
  holiday_rule                 varchar(16) NOT NULL DEFAULT 'NEXT',
  retry_policy                 jsonb,
  status                       varchar(40) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'PAUSED', 'COMPLETED', 'CANCELLED', 'FAILED_SUSPENDED')),
  consecutive_failures         integer NOT NULL DEFAULT 0,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
