-- virtual_account: Virtual account number routing incoming funds to a master account / sub-ledger
CREATE TABLE virtual_account (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  master_account_id            uuid NOT NULL REFERENCES deposit_account(id),
  virtual_account_number       varchar(34) NOT NULL,
  iban                         varchar(34),
  purpose                      varchar(40) NOT NULL CHECK (purpose IN ('COLLECTION', 'SUB_LEDGER', 'MARKETPLACE_SELLER', 'ESCROW', 'INVOICE', 'PAYROLL', 'CLIENT_MONEY')),
  owner_customer_id            uuid,
  owner_reference              varchar(128),
  ledger_account_id            uuid,
  currency                     char(3) NOT NULL,
  expected_amount              numeric(28,8),
  single_use                   boolean NOT NULL DEFAULT false,
  expires_at                   timestamptz,
  status                       varchar(40) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'SUSPENDED', 'CLOSED')),
  metadata                     jsonb,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_virtual_account_virtual_account_number UNIQUE (tenant_id, virtual_account_number),
  CONSTRAINT uq_virtual_account_iban UNIQUE (tenant_id, iban),
  CONSTRAINT uq_virtual_account_ledger_account_id UNIQUE (tenant_id, ledger_account_id)
);
